package com.syncro.expediente;

import android.Manifest;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.graphics.*;
import android.graphics.drawable.GradientDrawable;
import android.net.Uri;
import android.os.*;
import android.provider.MediaStore;
import android.view.*;
import android.widget.*;
import androidx.core.content.FileProvider;
import com.google.mlkit.vision.common.InputImage;
import com.google.mlkit.vision.text.*;
import com.google.mlkit.vision.text.latin.TextRecognizerOptions;
import org.json.*;
import java.io.*;
import java.util.*;

public class MainActivity extends Activity {
    private static final int REQ_CAMERA=10, REQ_PICK=11, REQ_CAM_PERMISSION=12;
    private LinearLayout body; private TextView status; private Database db; private File cameraFile;
    private final int NAVY=Color.rgb(15,23,42), BLUE=Color.rgb(37,99,235), BG=Color.rgb(248,250,252), GREEN=Color.rgb(4,120,87), MUTED=Color.rgb(71,85,105);

    @Override public void onCreate(Bundle b){super.onCreate(b); db=new Database(this); showHome();}
    private TextView text(String s,int sp,boolean bold){TextView v=new TextView(this);v.setText(s);v.setTextSize(sp);v.setTextColor(NAVY);v.setPadding(0,6,0,6);if(bold)v.setTypeface(null,1);return v;}
    private Button button(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextSize(15);b.setPadding(10,8,10,8);return b;}
    private LinearLayout panel(){LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);p.setPadding(20,18,20,18);GradientDrawable g=new GradientDrawable();g.setColor(Color.WHITE);g.setCornerRadius(24);g.setStroke(1,Color.rgb(226,232,240));p.setBackground(g);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,0,0,18);p.setLayoutParams(lp);return p;}
    private void shell(String title,String subtitle){ScrollView sc=new ScrollView(this);sc.setBackgroundColor(BG);body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(22,22,22,30);sc.addView(body);body.addView(text(title,27,true));TextView sub=text(subtitle,14,false);sub.setTextColor(MUTED);body.addView(sub);HorizontalScrollView hsv=new HorizontalScrollView(this);LinearLayout nav=new LinearLayout(this);nav.setOrientation(LinearLayout.HORIZONTAL);Button home=button("Inicio"), search=button("Expedientes"), invoices=button("Facturas"), export=button("Exportar");home.setOnClickListener(v->showHome());search.setOnClickListener(v->showSearch());invoices.setOnClickListener(v->showInvoices());export.setOnClickListener(v->exportAll());nav.addView(home);nav.addView(search);nav.addView(invoices);nav.addView(export);hsv.addView(nav);body.addView(hsv);setContentView(sc);}
    private void showHome(){shell("Expediente Inteligente","Captura documentos, reconoce su contenido y crea expedientes consultables.");LinearLayout p=panel();p.addView(text("Captura universal",20,true));p.addView(text("Fotografía o selecciona imagen, PDF o XML CFDI. El motor identifica el documento y guarda información estructurada.",15,false));Button cam=button("📷 Tomar foto");cam.setOnClickListener(v->camera());p.addView(cam);Button pick=button("🗂 Elegir imagen, PDF o XML");pick.setOnClickListener(v->pick());p.addView(pick);body.addView(p);LinearLayout f=panel();f.addView(text("Facturas inteligentes",19,true));f.addView(text("Si detecta un CFDI, guarda encabezado y conceptos en tablas separadas. Puedes buscar por UUID, RFC, folio, fecha, proveedor, receptor, descripción, clave de producto o importe.",14,false));Button go=button("Ver facturas guardadas");go.setOnClickListener(v->showInvoices());f.addView(go);body.addView(f);status=text("Listo para capturar.",14,true);status.setTextColor(GREEN);body.addView(status);}
    private void camera(){if(Build.VERSION.SDK_INT>=23&&checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.CAMERA},REQ_CAM_PERMISSION);return;}launchCamera();}
    private void launchCamera(){try{File dir=new File(getFilesDir(),"documents");dir.mkdirs();cameraFile=new File(dir,"capture_"+System.currentTimeMillis()+".jpg");Uri u=FileProvider.getUriForFile(this,getPackageName()+".files",cameraFile);Intent i=new Intent(MediaStore.ACTION_IMAGE_CAPTURE);i.putExtra(MediaStore.EXTRA_OUTPUT,u);i.addFlags(Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivityForResult(i,REQ_CAMERA);}catch(Exception e){toast("No fue posible abrir la cámara: "+e.getMessage());}}
    private void pick(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");i.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"image/*","application/pdf","text/xml","application/xml"});startActivityForResult(i,REQ_PICK);}
    @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==REQ_CAM_PERMISSION&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)launchCamera();}
    @Override protected void onActivityResult(int r,int result,Intent data){super.onActivityResult(r,result,data);if(result!=RESULT_OK)return;if(r==REQ_CAMERA&&cameraFile!=null)processUri(Uri.fromFile(cameraFile),cameraFile.getAbsolutePath());else if(r==REQ_PICK&&data!=null&&data.getData()!=null){Uri u=data.getData();try{getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}File copy=copyToPrivate(u);processUri(Uri.fromFile(copy),copy.getAbsolutePath());}}
    private File copyToPrivate(Uri u){try{String ext="bin";String mime=getContentResolver().getType(u);String name=u.toString().toLowerCase(Locale.ROOT);if("application/pdf".equals(mime)||name.endsWith(".pdf"))ext="pdf";else if((mime!=null&&mime.contains("xml"))||name.endsWith(".xml"))ext="xml";else if(mime!=null&&mime.contains("png"))ext="png";else if(mime!=null&&mime.startsWith("image/"))ext="jpg";File dir=new File(getFilesDir(),"documents");dir.mkdirs();File f=new File(dir,"doc_"+System.currentTimeMillis()+"."+ext);try(InputStream in=getContentResolver().openInputStream(u);OutputStream out=new FileOutputStream(f)){byte[] buf=new byte[8192];int n;while((n=in.read(buf))>0)out.write(buf,0,n);}return f;}catch(Exception e){throw new RuntimeException(e);}}
    private void processUri(Uri uri,String path){showProcessing();File f=new File(path);String low=path.toLowerCase(Locale.ROOT);if(low.endsWith(".xml")){processCfdiXml(f,path);}else if(low.endsWith(".pdf")){ocrPdf(f,path);}else{try{InputImage img=InputImage.fromFilePath(this,uri);ocrImage(img,path);}catch(Exception e){fail(e);}}}
    private void processCfdiXml(File f,String path){new Thread(()->{try{InvoiceParser.Invoice inv=InvoiceParser.fromCfdiXml(f);String raw=readText(f);runOnUiThread(()->showInvoiceResult(inv,raw,path,true));}catch(Exception e){runOnUiThread(()->fail(e));}}).start();}
    private String readText(File f)throws Exception{StringBuilder s=new StringBuilder();try(BufferedReader r=new BufferedReader(new InputStreamReader(new FileInputStream(f),"UTF-8"))){String l;while((l=r.readLine())!=null)s.append(l).append('\n');}return s.toString();}
    private void showProcessing(){shell("Analizando documento","OCR + clasificación + extracción estructurada");status=text("Leyendo el documento…",17,true);status.setTextColor(BLUE);body.addView(status);}
    private TextRecognizer recognizer(){return TextRecognition.getClient(TextRecognizerOptions.DEFAULT_OPTIONS);}
    private void ocrImage(InputImage img,String path){recognizer().process(img).addOnSuccessListener(t->finishAnalysis(t.getText(),path)).addOnFailureListener(this::fail);}
    private void ocrPdf(File f,String path){new Thread(()->{StringBuilder all=new StringBuilder();try(ParcelFileDescriptor p=ParcelFileDescriptor.open(f,ParcelFileDescriptor.MODE_READ_ONLY);android.graphics.pdf.PdfRenderer renderer=new android.graphics.pdf.PdfRenderer(p)){int pages=Math.min(renderer.getPageCount(),8);for(int i=0;i<pages;i++){android.graphics.pdf.PdfRenderer.Page pg=renderer.openPage(i);Bitmap bm=Bitmap.createBitmap(Math.max(1200,pg.getWidth()*2),Math.max(1600,pg.getHeight()*2),Bitmap.Config.ARGB_8888);Canvas c=new Canvas(bm);c.drawColor(Color.WHITE);pg.render(bm,null,null,android.graphics.pdf.PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);pg.close();final Object lock=new Object();final String[] txt={null};final Exception[] err={null};recognizer().process(InputImage.fromBitmap(bm,0)).addOnSuccessListener(t->{synchronized(lock){txt[0]=t.getText();lock.notify();}}).addOnFailureListener(e->{synchronized(lock){err[0]=e;lock.notify();}});synchronized(lock){while(txt[0]==null&&err[0]==null)lock.wait();}if(err[0]!=null)throw err[0];all.append("\n--- Página ").append(i+1).append(" ---\n").append(txt[0]);bm.recycle();}}catch(Exception e){runOnUiThread(()->fail(e));return;}runOnUiThread(()->finishAnalysis(all.toString(),path));}).start();}
    private void finishAnalysis(String raw,String path){DocumentClassifier.Result r=DocumentClassifier.analyze(raw);if("Factura / CFDI".equals(r.type)){InvoiceParser.Invoice inv=InvoiceParser.fromOcr(raw,r);showInvoiceResult(inv,raw,path,false);}else showResult(r,raw,path);}
    private EditText fieldEditor(LinearLayout p,String label,String value,LinkedHashMap<String,EditText> map){p.addView(text(label,12,true));EditText e=new EditText(this);e.setText(value==null?"":value);e.setTextSize(15);p.addView(e);map.put(label,e);return e;}
    private void showInvoiceResult(InvoiceParser.Invoice inv,String raw,String path,boolean exactXml){shell("Factura / CFDI detectado",exactXml?"Datos obtenidos directamente del XML CFDI.":"Datos reconstruidos por OCR; revisa los campos antes de guardar.");LinearLayout p=panel();p.addView(text(exactXml?"CFDI estructurado":"CFDI por OCR",21,true));TextView quality=text(exactXml?"Alta precisión: XML":"Precisión variable: foto/PDF",13,true);quality.setTextColor(exactXml?GREEN:BLUE);p.addView(quality);body.addView(p);LinkedHashMap<String,EditText> e=new LinkedHashMap<>();LinearLayout h=panel();h.addView(text("Encabezado de factura",19,true));fieldEditor(h,"UUID",inv.uuid,e);fieldEditor(h,"Serie",inv.serie,e);fieldEditor(h,"Folio",inv.folio,e);fieldEditor(h,"Fecha",inv.fecha,e);fieldEditor(h,"RFC emisor",inv.emisorRfc,e);fieldEditor(h,"Emisor",inv.emisorNombre,e);fieldEditor(h,"RFC receptor",inv.receptorRfc,e);fieldEditor(h,"Receptor",inv.receptorNombre,e);fieldEditor(h,"Moneda",inv.moneda,e);fieldEditor(h,"Método de pago",inv.metodoPago,e);fieldEditor(h,"Forma de pago",inv.formaPago,e);body.addView(h);LinearLayout totals=panel();totals.addView(text("Totales",19,true));EditText subtotal=fieldEditor(totals,"Subtotal",money(inv.subtotal),e);EditText taxes=fieldEditor(totals,"Impuestos",money(inv.impuestos),e);EditText total=fieldEditor(totals,"Total",money(inv.total),e);body.addView(totals);LinearLayout concepts=panel();concepts.addView(text("Conceptos detectados: "+inv.items.size(),19,true));if(inv.items.isEmpty())concepts.addView(text("No pude separar conceptos con suficiente seguridad. La factura se guardará y seguirá siendo buscable por su OCR completo.",14,false));else{int n=1;for(InvoiceParser.Item it:inv.items){concepts.addView(text(n+". "+it.descripcion,14,true));concepts.addView(text("Cant. "+plain(it.cantidad)+" · "+it.unidad+" · V.U. $"+money(it.valorUnitario)+" · Importe $"+money(it.importe),12,false));n++;}}body.addView(concepts);Button save=button("Guardar factura y conceptos");save.setOnClickListener(v->{try{inv.uuid=e.get("UUID").getText().toString().trim();inv.serie=e.get("Serie").getText().toString().trim();inv.folio=e.get("Folio").getText().toString().trim();inv.fecha=e.get("Fecha").getText().toString().trim();inv.emisorRfc=e.get("RFC emisor").getText().toString().trim();inv.emisorNombre=e.get("Emisor").getText().toString().trim();inv.receptorRfc=e.get("RFC receptor").getText().toString().trim();inv.receptorNombre=e.get("Receptor").getText().toString().trim();inv.moneda=e.get("Moneda").getText().toString().trim();inv.metodoPago=e.get("Método de pago").getText().toString().trim();inv.formaPago=e.get("Forma de pago").getText().toString().trim();inv.subtotal=num(subtotal.getText().toString());inv.impuestos=num(taxes.getText().toString());inv.total=num(total.getText().toString());JSONObject fields=new JSONObject();fields.put("UUID / Folio fiscal",inv.uuid);fields.put("RFC emisor",inv.emisorRfc);fields.put("RFC receptor",inv.receptorRfc);fields.put("Folio",inv.folio);fields.put("Fecha",inv.fecha);fields.put("Total",inv.total);String title=(inv.emisorNombre.isEmpty()?"Factura":inv.emisorNombre)+(inv.folio.isEmpty()?"":" · "+inv.folio);long docId=db.insert("Factura / CFDI",exactXml?0.99:0.86,path,raw,fields.toString(),"fiscal,factura,cfdi",title);long invoiceId=db.insertInvoice(docId,inv);toast("Factura #"+invoiceId+" guardada con "+inv.items.size()+" conceptos");showInvoiceDetail(invoiceId);}catch(Exception ex){fail(ex);}});body.addView(save);Button rawBtn=button("Ver contenido original reconocido");rawBtn.setOnClickListener(v->dialog(exactXml?"XML CFDI":"Texto OCR",raw));body.addView(rawBtn);}
    private String money(double d){return String.format(Locale.US,"%.2f",d);}private String plain(double d){return d==(long)d?String.valueOf((long)d):String.valueOf(d);}private double num(String s){try{return Double.parseDouble(s.replace(",",""));}catch(Exception e){return 0;}}
    private void showResult(DocumentClassifier.Result r,String raw,String path){shell("Documento reconocido","Revisa los datos antes de guardarlos. Puedes corregir cualquier campo detectado.");LinearLayout summary=panel();summary.addView(text(r.type,22,true));summary.addView(text("Confianza aproximada: "+Math.round(r.confidence*100)+"%",14,false));body.addView(summary);LinearLayout fields=panel();fields.addView(text("Datos extraídos",19,true));LinkedHashMap<String,EditText> editors=new LinkedHashMap<>();for(Map.Entry<String,String> x:r.fields.entrySet())fieldEditor(fields,x.getKey(),x.getValue(),editors);body.addView(fields);LinearLayout extra=panel();extra.addView(text("Nombre para el expediente",14,true));EditText title=new EditText(this);extra.addView(title);body.addView(extra);Button save=button("Guardar expediente");save.setOnClickListener(v->{try{JSONObject j=new JSONObject();for(Map.Entry<String,EditText> x:editors.entrySet())j.put(x.getKey(),x.getValue().getText().toString().trim());long id=db.insert(r.type,r.confidence,path,raw,j.toString(),String.join(",",r.tags),title.getText().toString().trim());toast("Expediente #"+id+" guardado");showSearch();}catch(Exception ex){fail(ex);}});body.addView(save);}
    private void showSearch(){shell("Expedientes","Busca por nombre, CURP, RFC, folio, tipo, domicilio o cualquier texto reconocido.");EditText q=new EditText(this);q.setHint("Buscar en todos los documentos…");body.addView(q);Button b=button("Buscar");body.addView(b);LinearLayout results=new LinearLayout(this);results.setOrientation(LinearLayout.VERTICAL);body.addView(results);Runnable load=()->{results.removeAllViews();android.database.Cursor c=db.search(q.getText().toString());while(c.moveToNext()){long id=c.getLong(0);LinearLayout p=panel();String ttl=c.getString(4);p.addView(text((ttl==null||ttl.isEmpty()?c.getString(2):ttl),17,true));p.addView(text(c.getString(1),12,false));p.setOnClickListener(v->showDetail(id));results.addView(p);}if(c.getCount()==0)results.addView(text("No hay resultados todavía.",14,false));c.close();};b.setOnClickListener(v->load.run());load.run();}
    private void showInvoices(){shell("Facturas","Consulta facturas y conceptos por cualquier dato.");EditText q=new EditText(this);q.setHint("UUID, RFC, folio, proveedor, receptor, concepto…");body.addView(q);Button search=button("Buscar facturas");body.addView(search);LinearLayout results=new LinearLayout(this);results.setOrientation(LinearLayout.VERTICAL);body.addView(results);Runnable load=()->{results.removeAllViews();android.database.Cursor c=db.searchInvoices(q.getText().toString());while(c.moveToNext()){long id=c.getLong(0);LinearLayout p=panel();String who=c.getString(7);if(who==null||who.isEmpty())who=c.getString(6);String fol=((c.getString(4)==null?"":c.getString(4))+" "+(c.getString(5)==null?"":c.getString(5))).trim();p.addView(text((who==null||who.isEmpty()?"Factura":who)+(fol.isEmpty()?"":" · "+fol),17,true));p.addView(text("Fecha: "+nz(c.getString(2))+" · Total $"+money(c.getDouble(12))+" "+nz(c.getString(13)),13,false));p.addView(text("UUID: "+nz(c.getString(3))+"\nEmisor: "+nz(c.getString(6))+" · Receptor: "+nz(c.getString(8)),12,false));p.setOnClickListener(v->showInvoiceDetail(id));results.addView(p);}if(c.getCount()==0)results.addView(text("No hay facturas que coincidan.",14,false));c.close();};search.setOnClickListener(v->load.run());load.run();}
    private String nz(String s){return s==null?"":s;}
    private void showInvoiceDetail(long invoiceId){try{InvoiceParser.Invoice inv=db.getInvoice(invoiceId);shell("Factura #"+invoiceId,(inv.emisorNombre.isEmpty()?inv.emisorRfc:inv.emisorNombre));LinearLayout h=panel();h.addView(text("Datos fiscales",19,true));h.addView(text("UUID: "+inv.uuid,13,false));h.addView(text("Serie/Folio: "+inv.serie+" "+inv.folio,13,false));h.addView(text("Fecha: "+inv.fecha,13,false));h.addView(text("Emisor: "+inv.emisorNombre+" · "+inv.emisorRfc,13,false));h.addView(text("Receptor: "+inv.receptorNombre+" · "+inv.receptorRfc,13,false));h.addView(text("Subtotal $"+money(inv.subtotal)+" · Impuestos $"+money(inv.impuestos)+" · TOTAL $"+money(inv.total)+" "+inv.moneda,15,true));body.addView(h);LinearLayout t=panel();t.addView(text("Conceptos ("+inv.items.size()+")",19,true));if(inv.items.isEmpty())t.addView(text("No hay conceptos estructurados para esta factura.",14,false));else{int n=1;for(InvoiceParser.Item it:inv.items){t.addView(text(n+". "+it.descripcion,14,true));t.addView(text("Clave: "+it.claveProdServ+" · Cant: "+plain(it.cantidad)+" "+it.unidad+" · V.U. $"+money(it.valorUnitario)+" · Importe $"+money(it.importe),12,false));n++;}}body.addView(t);Button doc=button("Abrir expediente original");doc.setOnClickListener(v->showDetail(inv.documentId));body.addView(doc);}catch(Exception e){fail(e);}}
    private void showDetail(long id){try{JSONObject o=db.get(id);shell("Expediente #"+id,o.optString("type"));LinearLayout p=panel();p.addView(text(o.optString("title",o.optString("type")),20,true));p.addView(text("Creado: "+o.optString("createdAt"),13,false));JSONObject f=o.optJSONObject("fields");if(f!=null){Iterator<String> ks=f.keys();while(ks.hasNext()){String k=ks.next();p.addView(text(k+": "+f.optString(k),14,false));}}body.addView(p);Button raw=button("Ver OCR / XML completo");raw.setOnClickListener(v->dialog("Contenido reconocido",o.optString("rawText")));body.addView(raw);}catch(Exception e){fail(e);}}
    private void exportAll(){try{JSONArray a=db.all();File dir=new File(getFilesDir(),"documents");dir.mkdirs();File f=new File(dir,"expedientes_"+System.currentTimeMillis()+".json");try(FileWriter w=new FileWriter(f)){w.write(a.toString(2));}Uri u=FileProvider.getUriForFile(this,getPackageName()+".files",f);Intent i=new Intent(Intent.ACTION_SEND);i.setType("application/json");i.putExtra(Intent.EXTRA_STREAM,u);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(i,"Exportar expedientes"));}catch(Exception e){fail(e);}}
    private void dialog(String title,String msg){new AlertDialog.Builder(this).setTitle(title).setMessage(msg).setPositiveButton("Cerrar",null).show();}
    private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
    private void fail(Exception e){toast("Error: "+e.getMessage());showHome();}
}
